from functools import wraps

def prefix(tag):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return f"[{tag}] {func(*args, **kwargs)}"
        return wrapper
    return decorator

@prefix("INFO")
def get_msg(): return "System Ready"
print(get_msg())  # Output: [INFO] System Ready

